// SBOM report payloads. FK to scan_jobs. Content in blobs (not inline).
type SbomResult struct {
	ID             string  `db:"id" json:"id"`
	ScanJobID      string  `db:"scan_job_id" json:"scan_job_id"`
	SbomFormat     string  `db:"sbom_format" json:"sbom_format"`
	SpecVersion    string  `db:"spec_version" json:"spec_version"`
	BlobID         *string `db:"blob_id" json:"blob_id"`
	ComponentCount int32   `db:"component_count" json:"component_count"`
}

type SbtArtifact struct {
	ID           string     `db:"id" json:"id"`
	RepositoryID string     `db:"repository_id" json:"repository_id"`
	GroupID      string     `db:"group_id" json:"group_id"`
	ArtifactID   string     `db:"artifact_id" json:"artifact_id"`
	Version      string     `db:"version" json:"version"`
	ScalaVersion string     `db:"scala_version" json:"scala_version"`
	Filename     string     `db:"filename" json:"filename"`
	CreatedAt    time.Time  `db:"created_at" json:"created_at"`
	UpdatedAt    time.Time  `db:"updated_at" json:"updated_at"`
	BlobID       string     `db:"blob_id" json:"blob_id"`
	DeletedAt    *time.Time `db:"deleted_at" json:"deleted_at"`
	DeletedBy    *string    `db:"deleted_by" json:"deleted_by"`
}

// Parent table for all scan work (vuln, license, secret, sbom, ai). Result payloads are in: vuln_results, license_results, secret_results, sbom_results, ai_results.
type ScanJob struct {
	ID            string `db:"id" json:"id"`
	ArtifactRefID string `db:"artifact_ref_id" json:"artifact_ref_id"`
	ScanType      string `db:"scan_type" json:"scan_type"`
	// Scanner implementation: osv, trivy, grype, internal, etc. NULL = default for type.
	Scanner      *string    `db:"scanner" json:"scanner"`
	Status       string     `db:"status" json:"status"`
	ErrorMessage *string    `db:"error_message" json:"error_message"`
	StartedAt    *time.Time `db:"started_at" json:"started_at"`
	CompletedAt  *time.Time `db:"completed_at" json:"completed_at"`
	CreatedAt    time.Time  `db:"created_at" json:"created_at"`
	UpdatedAt    time.Time  `db:"updated_at" json:"updated_at"`
}

// Secret detection payloads. FK to scan_jobs.
type SecretResult struct {
	ID           string          `db:"id" json:"id"`
	ScanJobID    string          `db:"scan_job_id" json:"scan_job_id"`
	Findings     json.RawMessage `db:"findings" json:"findings"`
	FindingCount int32           `db:"finding_count" json:"finding_count"`
	Quarantined  bool            `db:"quarantined" json:"quarantined"`
}

// Configured storage backends for artifact persistence
type StorageBackend struct {
	ID            string          `db:"id" json:"id"`
	Name          string          `db:"name" json:"name"`
	Kind          string          `db:"kind" json:"kind"`
	IsDefault     bool            `db:"is_default" json:"is_default"`
	Config        json.RawMessage `db:"config" json:"config"`
	Status        string          `db:"status" json:"status"`
	StatusMessage *string         `db:"status_message" json:"status_message"`
	LastCheckedAt *time.Time      `db:"last_checked_at" json:"last_checked_at"`
	CreatedAt     time.Time       `db:"created_at" json:"created_at"`
	UpdatedAt     time.Time       `db:"updated_at" json:"updated_at"`
}

// Storage quotas and usage tracking per repository
type StorageQuota struct {
	ID                   string    `db:"id" json:"id"`
	RepositoryID         string    `db:"repository_id" json:"repository_id"`
	MaxSizeBytes         int64     `db:"max_size_bytes" json:"max_size_bytes"`
	MaxArtifactCount     int64     `db:"max_artifact_count" json:"max_artifact_count"`
	WarnThresholdPercent int32     `db:"warn_threshold_percent" json:"warn_threshold_percent"`
	CurrentSizeBytes     int64     `db:"current_size_bytes" json:"current_size_bytes"`
	CurrentArtifactCount int64     `db:"current_artifact_count" json:"current_artifact_count"`
	CreatedAt            time.Time `db:"created_at" json:"created_at"`
	UpdatedAt            time.Time `db:"updated_at" json:"updated_at"`
}

type SystemSetting struct {
	Key       string    `db:"key" json:"key"`
	Value     string    `db:"value" json:"value"`
	CreatedAt time.Time `db:"created_at" json:"created_at"`
	UpdatedAt time.Time `db:"updated_at" json:"updated_at"`
}

// Vulnerability scan payloads. FK to scan_jobs.
type VulnResult struct {
	ID              string          `db:"id" json:"id"`
	ScanJobID       string          `db:"scan_job_id" json:"scan_job_id"`
	Vulnerabilities json.RawMessage `db:"vulnerabilities" json:"vulnerabilities"`
	VulnCount       int32           `db:"vuln_count" json:"vuln_count"`
	CriticalCount   int32           `db:"critical_count" json:"critical_count"`
	HighCount       int32           `db:"high_count" json:"high_count"`
	MediumCount     int32           `db:"medium_count" json:"medium_count"`
	LowCount        int32           `db:"low_count" json:"low_count"`
	Quarantined     bool            `db:"quarantined" json:"quarantined"`
	PackageName     *string         `db:"package_name" json:"package_name"`
	PackageVersion  *string         `db:"package_version" json:"package_version"`
	Ecosystem       *string         `db:"ecosystem" json:"ecosystem"`
	// Scanners that did not produce a result (status failed or partial).
	FailedScanners []string `db:"failed_scanners" json:"failed_scanners"`
}

// Webhook subscriptions for artifact lifecycle events
type Webhook struct {
	ID           string  `db:"id" json:"id"`
	RepositoryID *string `db:"repository_id" json:"repository_id"`
	Name         string  `db:"name" json:"name"`
	Url          string  `db:"url" json:"url"`
	// AES-256-GCM encrypted HMAC-SHA256 signing secret. Plaintext MUST NOT be stored here. Encrypt before write, decrypt after read.
	SecretEnc      *string   `db:"secret_enc" json:"secret_enc"`
	Enabled        bool      `db:"enabled" json:"enabled"`
	Events         []string  `db:"events" json:"events"`
	ContentType    string    `db:"content_type" json:"content_type"`
	SslVerify      bool      `db:"ssl_verify" json:"ssl_verify"`
	MaxRetries     int32     `db:"max_retries" json:"max_retries"`
	TimeoutSeconds int32     `db:"timeout_seconds" json:"timeout_seconds"`
	CreatedAt      time.Time `db:"created_at" json:"created_at"`
	UpdatedAt      time.Time `db:"updated_at" json:"updated_at"`
}

// Webhook delivery attempts and history
type WebhookDelivery struct {
	ID             string          `db:"id" json:"id"`
	WebhookID      string          `db:"webhook_id" json:"webhook_id"`
	EventType      string          `db:"event_type" json:"event_type"`
	Payload        json.RawMessage `db:"payload" json:"payload"`
	Status         string          `db:"status" json:"status"`
	ResponseStatus *int32          `db:"response_status" json:"response_status"`
	ResponseBody   *string         `db:"response_body" json:"response_body"`
	AttemptCount   int32           `db:"attempt_count" json:"attempt_count"`
	NextRetryAt    *time.Time      `db:"next_retry_at" json:"next_retry_at"`
	DeliveredAt    *time.Time      `db:"delivered_at" json:"delivered_at"`
	CreatedAt      time.Time       `db:"created_at" json:"created_at"`
	UpdatedAt      time.Time       `db:"updated_at" json:"updated_at"`
}
